import csv
import io


def parse_csv(raw_csv: str):
    expected_width = 7

    reader = csv.reader(io.StringIO(raw_csv, newline=""), delimiter=",", quotechar='"', strict=False)
    parsed_rows = list(reader)

    if not parsed_rows:
        return {"columns": [], "rows": []}

    candidates = [
        (index, row)
        for index, row in enumerate(parsed_rows)
        if len(row) == expected_width
        and sum(1 for value in row if value.strip()) >= 2
    ]

    if candidates:
        header_index, header = max(
            candidates,
            key=lambda item: sum(1 for value in item[1] if value.strip()),
        )
    else:
        header_index = next(
            (index for index, row in enumerate(parsed_rows) if any(value.strip() for value in row)),
            0,
        )
        header = parsed_rows[header_index]

    data_rows = parsed_rows[header_index + 1:]
    width = max(
        expected_width,
        len(header),
        max((len(row) for row in data_rows), default=0),
    )

    columns = list(header)
    while len(columns) < width:
        columns.append(f"Unnamed: {len(columns) + 1}")

    rows = []
    for row in data_rows:
        normalized = list(row[:width])
        normalized.extend([""] * (width - len(normalized)))
        rows.append(normalized)

    return {"columns": columns, "rows": rows}
